import { test, beforeEach } from "node:test";
import assert from "node:assert/strict";
import { app } from "../src/api/routes.ts";
import { resetUsers } from "../src/auth/users.ts";
import { resetSessions } from "../src/auth/session.ts";

const call = (method: string, path: string, body?: unknown, token?: string) =>
  app({ method, path, body, headers: token ? { authorization: `Bearer ${token}` } : {} });

beforeEach(() => {
  resetUsers();
  resetSessions();
});

test("signup creates account and signs in user", async () => {
  const res = await call("POST", "/api/signup", {
    email: "grace@example.com",
    name: "Grace",
    password: "securepassword123",
  });
  assert.equal(res.status, 201);
  const body = res.body as { token: string; user: { id: string; email: string; name: string } };
  assert.ok(body.token);
  assert.equal(body.user.email, "grace@example.com");
  assert.equal(body.user.name, "Grace");

  // Verify session token works with /api/me
  const me = await call("GET", "/api/me", undefined, body.token);
  assert.equal(me.status, 200);
  assert.deepEqual(me.body, body.user);
});

test("signup returns 400 on UserError", async () => {
  // Invalid email
  const res1 = await call("POST", "/api/signup", {
    email: "invalid-email",
    name: "Grace",
    password: "securepassword123",
  });
  assert.equal(res1.status, 400);
  assert.deepEqual(res1.body, { error: "invalid email" });

  // Password too short
  const res2 = await call("POST", "/api/signup", {
    email: "grace@example.com",
    name: "Grace",
    password: "short",
  });
  assert.equal(res2.status, 400);
  assert.deepEqual(res2.body, { error: "password must be at least 8 characters" });

  // Duplicate email
  await call("POST", "/api/signup", {
    email: "grace@example.com",
    name: "Grace",
    password: "securepassword123",
  });
  const res3 = await call("POST", "/api/signup", {
    email: "grace@example.com",
    name: "Grace Duplicate",
    password: "securepassword123",
  });
  assert.equal(res3.status, 400);
  assert.deepEqual(res3.body, { error: "email already registered" });
});
